from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def check_expired(key, t):
        if key in cache:
            value, write_time = cache[key]
            if t >= write_time + ttl:
                del cache[key]

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        check_expired(key, t)

        if kind == 'put':
            value = op[3]
            if key in cache:
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t)
        elif kind == 'get':
            if key in cache:
                value, write_time = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

